import { test, expect } from '@playwright/test';

test.describe('Checkout Information Form Validation', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('https://www.saucedemo.com');
    await page.fill('[data-test="username"]', 'standard_user');
    await page.fill('[data-test="password"]', 'secret_sauce');
    await page.click('[data-test="login-button"]');
    await page.click('[data-test="add-to-cart-sauce-labs-backpack"]');
    await page.click('.shopping_cart_link');
    await page.click('[data-test="checkout"]');
  });

  test('should show error when postal code is not filled', async ({ page }) => {
    await page.fill('[data-test="firstName"]', 'Saif');
    await page.fill('[data-test="lastName"]', 'Afzal');
    await page.click('[data-test="continue"]');

    const errorMessage = await page.getByTestId('error');
    await expect(errorMessage).toContainText('Postal Code is required');
  });

  test('should not show error when all fields are filled', async ({ page }) => {
    await page.fill('[data-test="firstName"]', 'Saif');
    await page.fill('[data-test="lastName"]', 'Afzal');
    await page.fill('[data-test="postalCode"]', '12345');
    await page.click('[data-test="continue"]');

    const pageTitle = await page.getByRole('heading', { name: /overview/i });
    await expect(pageTitle).toBeVisible();
  });
});
